// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { findNodes } from "../../../main/frontend/graph-explorer/graph-find.ts";

const node = (id, label, kind = "iri") => ({ id, label, kind });
const nodes = [
  node("http://example.org/carol", "Carol Christensen"),
  node("http://example.org/oslo", "Oslo"),
  node("http://example.org/osloMet", "OsloMet University"),
  node("http://example.org/bob", "Bob Berg"),
  node("http://example.org/people/olsen", "Kari Olsen"),
  node("http://example.org/acme", "Acme Corp"),
];

test("an exact label comes first, then labels and words that start with the term, then the rest", () => {
  assert.deepEqual(findNodes(nodes, "oslo").map((match) => match.node.label), ["Oslo", "OsloMet University"]);
  assert.deepEqual(findNodes(nodes, "ol").map((match) => match.node.label), ["Kari Olsen", "Carol Christensen"]);
  assert.deepEqual(findNodes(nodes, "BERG").map((match) => match.node.label), ["Bob Berg"]);
});

test("the IRI is searched too, and says where the term was found", () => {
  const [match] = findNodes(nodes, "people/");
  assert.equal(match.node.label, "Kari Olsen");
  assert.equal(match.in, "iri");
  assert.equal(findNodes(nodes, "acme")[0].in, "label");
});

test("blank terms find nothing and the number of matches is limited", () => {
  assert.deepEqual(findNodes(nodes, "   "), []);
  const many = Array.from({ length: 30 }, (_, index) => node(`urn:n${index}`, `Node ${index}`));
  assert.equal(findNodes(many, "node").length, 8);
  assert.equal(findNodes(many, "node", 3).length, 3);
});

test("a blank node is found by its label, not by the internal ID that stands for it", () => {
  const blanks = [
    node('__rdf_scoped_bnode__:["537346d6e5:1","b0"]', "Bryggen 1", "blank"),
    node("<_:node1address>", "Storgata 2", "blank"),
  ];
  assert.deepEqual(findNodes(blanks, "scoped"), []);
  assert.deepEqual(findNodes(blanks, "<_:"), []);
  assert.deepEqual(findNodes(blanks, "node1"), []);
  assert.deepEqual(findNodes(blanks, "bryggen").map((match) => match.node.label), ["Bryggen 1"]);
});
